PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS dossier_audit_runs (run_id TEXT PRIMARY KEY NOT NULL,benchmark_name TEXT NOT NULL,expected_ticker_pages INTEGER NOT NULL,expected_distinct_companies INTEGER NOT NULL,verified_at TEXT NOT NULL,notes TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dossier_audit_members (run_id TEXT NOT NULL,ticker TEXT NOT NULL,source_count INTEGER NOT NULL,claim_count INTEGER NOT NULL,completeness INTEGER NOT NULL,verified_at TEXT NOT NULL,PRIMARY KEY(run_id,ticker),FOREIGN KEY(run_id) REFERENCES dossier_audit_runs(run_id) ON DELETE CASCADE);
DELETE FROM dossier_audit_members WHERE run_id='2026-08-05-complete-benchmark';
















































































































































































































